arguments.content:
#!/bin/bash
fail=0
t=$(mktemp); printf '# room\tdate\tstart\tend\twho\naoi\t2026-01-05\t09:00\t10:00\tx\nkaede\t2026-01-05\t13:00\t14:00\ty\n' > "$t"
out=$(BOOKINGS=$t bash src/cancel.sh aoi 2026-01-05 09:00) || { echo "cancel failed"; fail=1; }
[ "$out" = 'cancelled: aoi 2026-01-05 09:00-10:00 x' ] || { echo "cancel output: $out"; fail=1; }
! grep -q '^aoi.2026-01-05.09:00' "$t" || { echo "booking still there"; fail=1; }
grep -qF '# room	date	start	end	who' "$t" || { echo "header line lost"; fail=1; }
grep -qF 'kaede	2026-01-05	13:00	14:00	y' "$t" || { echo "other booking (kaede) lost"; fail=1; }
err=$(BOOKINGS=$t bash src/cancel.sh aoi 2026-01-05 11:00 2>&1 >/dev/null); c=$?
out=$(BOOKINGS=$t bash src/cancel.sh aoi 2026-01-05 11:00 2>/dev/null)
[ $c = 1 ] || { echo "not found should exit 1, got $c"; fail=1; }
[ -z "$out" ] || { echo "not found should print nothing to stdout: $out"; fail=1; }
[ "$err" = 'not found: aoi 2026-01-05 11:00' ] || { echo "not found message on stderr: $err"; fail=1; }
err=$(bash src/cancel.sh aoi 2026-01-05 2>&1 >/dev/null); c=$?
[ $c = 2 ] || { echo "usage should exit 2, got $c"; fail=1; }
[ "$err" = 'usage: cancel.sh ROOM DATE START' ] || { echo "usage message on stderr: $err"; fail=1; }
t2=$(mktemp); printf '# room\tdate\tstart\tend\twho\nkaede\t2026-01-05\t09:00\t10:00\tz\naoi\t2026-01-05\t09:00\t10:00\tx\n' > "$t2"
out=$(BOOKINGS=$t2 bash src/cancel.sh aoi 2026-01-05 09:00) || { echo "cancel (other room, same slot) failed"; fail=1; }
[ "$out" = 'cancelled: aoi 2026-01-05 09:00-10:00 x' ] || { echo "cancel output (other room): $out"; fail=1; }
grep -qF 'kaede	2026-01-05	09:00	10:00	z' "$t2" || { echo "other room's booking at the same slot was removed"; fail=1; }
! grep -qF 'aoi	2026-01-05	09:00' "$t2" || { echo "booking still there (other room case)"; fail=1; }
rm -f "$t" "$t2"; exit $fail

